struct Wrapper<T> {
    value: T,
}

impl<T> Wrapper<T> {
    fn get(&self) -> &T {
        &self.value
    }
}

fn main() {
    let a = Wrapper { value: "hi" };
    let b = Wrapper { value: 42 };
    println!("{} {}", a.get(), b.get());
}

