struct Pair<T, U> {
    left: T,
    right: U,
}

impl<T, U> Pair<T, U> {
    fn swap(self) -> Pair<U, T> {
        Pair { left: self.right, right: self.left }
    }
}

fn main() {
    let p = Pair { left: 1, right: "one" };
    let q = p.swap();
    println!("{} {}", q.left, q.right);
}
